mapper.update:
update t1500_manager_assignment
set del_yn=#{delYn},
update_dt=SYSDATE,
update_id=#{updateId}
where inst_id=#{instId}
and   dept_id=#{deptId}
and	  complain_category_id=#{complainCategoryId}
and   account_id=#{accountId}

mapper.select:
SELECT COUNT(1) FROM t1500_manager_assignment ma JOIN t1000_institution i ON i.inst_id = ma.inst_id JOIN t1000_department d ON d.dept_id = ma.dept_id JOIN t2000_complain_category cc ON cc.complain_category_id = ma.complain_category_id JOIN t1000_account a ON a.account_id = ma.account_id JOIN t1000_user u ON u.user_no = a.user_no
AND ma.del_yn = #{delYn}
AND ma.dept_id = #{deptId}
AND ma.complain_category_id = #{complainCategoryId}
AND ma.account_id = #{accountId}
AND i.inst_name LIKE '%' || #{instName} || '%'
AND d.dept_name LIKE '%' || #{deptName} || '%'
AND cc.category_name LIKE '%' || #{categoryName} || '%'
AND a.login_id LIKE '%' || #{loginId} || '%'
AND u.user_name LIKE '%' || #{userName} || '%'
AND ma.create_dt >= TO_DATE(#{createDt}, 'YYYY-MM-DD') AND ma.create_dt < TO_DATE(#{updateDt}, 'YYYY-MM-DD') + 1
AND ma.update_dt >= TO_DATE(#{createDt}, 'YYYY-MM-DD') AND ma.update_dt < TO_DATE(#{updateDt}, 'YYYY-MM-DD') + 1
